import [printf], [malloc], [free] from "std/c.bpl";

frame main() ret int {
    # Allocate memory for a single integer
    local p: *int = cast<*int>(malloc(sizeof<int>()));

    if (p == nullptr) {
        printf("Allocation failed!\n");
        return 1;
    }

    # Store a value
    *p = 42;
    printf("Value at p: %d\n", *p);

    # Modify it
    *p = *p * 2;
    printf("After doubling: %d\n", *p);

    # Free the memory
    free(cast<*void>(p));
    printf("Memory freed!\n");

    # DANGER: p is now a dangling pointer!
    # Don't use p after free
    # *p = 100;  # UNDEFINED BEHAVIOR!

    return 0;
}

import [printf], [malloc], [free] from "std/c.bpl";

frame main() ret int {
    local size: int = 5;

    # Allocate array of integers
    local arr: *int = cast<*int>(malloc(cast<long>(size) * sizeof<int>()));

    if (arr == nullptr) {
        printf("Allocation failed!\n");
        return 1;
    }

    # Initialize array
    loop (local i: int = 0; i < size; i = i + 1) {
        *(arr + i) = (i + 1) * 10;
    }

    # Print array
    printf("Dynamic array: ");
    loop (local i: int = 0; i < size; i = i + 1) {
        printf("%d ", *(arr + i));
    }
    printf("\n");

    # Calculate sum
    local sum: int = 0;
    loop (local i: int = 0; i < size; i = i + 1) {
        sum = sum + *(arr + i);
    }
    printf("Sum: %d\n", sum);

    # Free the array
    free(cast<*void>(arr));
    printf("Array freed!\n");

    return 0;
}

import [printf], [malloc], [free] from "std/c.bpl";

struct Buffer {
    data: *int,
    size: int,
}

frame processData(size: int) ret bool {
    local buf: Buffer;
    buf.data = cast<*int>(malloc(cast<long>(size) * sizeof<int>()));
    buf.size = size;

    if (buf.data == nullptr) {
        return false;
    }

    # defer ensures cleanup happens when function exits
    defer {
        printf("Cleaning up buffer...\n");
        free(cast<*void>(buf.data));
    }

    # Initialize
    loop (local i: int = 0; i < size; i = i + 1) {
        *(buf.data + i) = i * i;
    }

    # Process
    printf("Squares: ");
    loop (local i: int = 0; i < size; i = i + 1) {
        printf("%d ", *(buf.data + i));
    }
    printf("\n");

    # Simulate error check
    if (size > 10) {
        printf("Size too large!\n");
        return false;  # defer still runs!
    }

    printf("Processing complete!\n");
    return true;  # defer runs here too
}

frame main() ret int {
    printf("=== Test 1 (size=5) ===\n");
    processData(5);

    printf("\n=== Test 2 (size=15) ===\n");
    processData(15);

    return 0;
}

import [printf], [malloc], [free] from "std/c.bpl";

struct Person {
    name: string,
    age: int,
}

frame createPerson(name: string, age: int) ret *Person {
    local p: *Person = cast<*Person>(malloc(sizeof<Person>()));
    if (p == nullptr) {
        return nullptr;
    }
    p.name = name;
    p.age = age;
    return p;
}

frame freePerson(p: *Person) {
    if (p != nullptr) {
        free(cast<*void>(p));
    }
}

frame main() ret int {
    # Create people on heap
    local alice: *Person = createPerson("Alice", 30);
    local bob: *Person = createPerson("Bob", 25);

    if (alice == nullptr || bob == nullptr) {
        printf("Failed to allocate!\n");
        return 1;
    }

    printf("Person 1: %s, age %d\n", alice.name, alice.age);
    printf("Person 2: %s, age %d\n", bob.name, bob.age);

    # Modify through pointer
    alice.age = alice.age + 1;
    printf("After birthday: %s is now %d\n", alice.name, alice.age);

    # Clean up
    freePerson(alice);
    freePerson(bob);
    printf("Memory cleaned up!\n");

    return 0;
}

import [printf], [malloc], [free] from "std/c.bpl";

# A vector that manages its own memory
struct IntVec {
    data: *int,
    len: int,
    cap: int,

    # Constructor
    frame create(initialCap: int) ret IntVec {
        local v: IntVec;
        v.cap = initialCap;
        v.len = 0;
        v.data = cast<*int>(malloc(cast<long>(initialCap) * sizeof<int>()));
        return v;
    }

    # Destructor
    frame destroy(this: *IntVec) {
        if (this.data != nullptr) {
            free(cast<*void>(this.data));
            this.data = nullptr;
            this.len = 0;
            this.cap = 0;
        }
    }

    frame push(this: *IntVec, value: int) ret bool {
        if (this.len >= this.cap) {
            printf("Vector full!\n");
            return false;
        }
        *(this.data + this.len) = value;
        this.len = this.len + 1;
        return true;
    }

    frame get(this: *IntVec, index: int) ret int {
        return *(this.data + index);
    }

    frame print(this: *IntVec) {
        printf("[");
        loop (local i: int = 0; i < this.len; i = i + 1) {
            printf("%d", this.get(i));
            if (i < this.len - 1) {
                printf(", ");
            }
        }
        printf("]\n");
    }
}

frame main() ret int {
    local vec: IntVec = IntVec.create(10);

    defer {
        printf("Destroying vector...\n");
        vec.destroy();
    }

    vec.push(10);
    vec.push(20);
    vec.push(30);
    vec.push(40);

    printf("Vector length: %d\n", vec.len);
    printf("Vector contents: ");
    vec.print();

    printf("Element at 2: %d\n", vec.get(2));

    return 0;
}

