import [printf], [malloc], [free] from "std/c.bpl";

struct StringBuffer {
    data: *char,
    len: int,
    cap: int,

    frame create(cap: int) ret StringBuffer {
        local sb: StringBuffer;
        sb.data = cast<*char>(malloc(cap));
        sb.len = 0;
        sb.cap = cap;
        return sb;
    }

    frame destroy(this: *StringBuffer) {
        if (this.data != nullptr) {
            free(cast<*void>(this.data));
            this.data = nullptr;
        }
    }

    frame append(this: *StringBuffer, c: char) ret bool {
        if (this.len >= this.cap - 1) {
            return false;
        }
        *(this.data + this.len) = c;
        this.len = this.len + 1;
        *(this.data + this.len) = cast<char>(0);  # Null terminate
        return true;
    }
}

frame main() ret int {
    local sb: StringBuffer = StringBuffer.create(20);
    defer { sb.destroy(); }

    sb.append('H');
    sb.append('e');
    sb.append('l');
    sb.append('l');
    sb.append('o');

    printf("Buffer: %s\n", sb.data);
    printf("Length: %d\n", sb.len);

    return 0;
}
